class Main {
  static String value(String json, String key) {
    String mark = "\"" + key + "\":\"";
    int start = json.indexOf(mark);
    if (start < 0) return null;
    start += mark.length();
    int end = json.indexOf('"', start);
    return json.substring(start, end);
  }
  public static void main(String[] args) {
    String json = "{\"id\":42,\"name\":\"sato\",\"city\":\"tokyo\"}";
    System.out.println(value(json, "name"));
    System.out.println(value(json, "city"));
    System.out.println(value(json, "age"));
  }
}

class Main {
  static int intValue(String json, String key) {
    String mark = "\"" + key + "\":";
    int start = json.indexOf(mark);
    start += mark.length();
    int end = json.indexOf(',', start);
    if (end < 0) end = json.indexOf('}', start);
    return Integer.parseInt(json.substring(start, end));
  }
  public static void main(String[] args) {
    System.out.println(intValue("{\"id\":42,\"name\":\"sato\"}", "id"));
  }
}

